insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0820','braille','Letters','hard','classic','Which letter uses Braille dots 1, 2, 3, and 5?','["R","P","Q","L"]'::jsonb,'R','R adds dot 3 to the pattern for H, giving dots 1, 2, 3, and 5.',10,2,array['letters'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0821','braille','Letters','hard','classic','Which dots represent the Braille letter T?','["Dots 2, 3, 4, and 5","Dots 2, 3, and 4","Dots 1, 3, 4, and 5","Dots 2, 4, and 5"]'::jsonb,'Dots 2, 3, 4, and 5','T adds dot 3 to the pattern for J, giving dots 2, 3, 4, and 5.',10,2,array['letters'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0822','braille','Letters','medium','classic','Which letter uses Braille dots 1, 3, and 6?','["U","K","X","Z"]'::jsonb,'U','U adds dots 3 and 6 to the pattern for A, giving dots 1, 3, and 6.',10,2,array['letters'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0823','braille','Letters','hard','classic','Which dots represent the Braille letter V?','["Dots 1, 2, 3, and 6","Dots 1, 3, and 6","Dots 1, 2, 3, and 5","Dots 2, 4, 5, and 6"]'::jsonb,'Dots 1, 2, 3, and 6','V adds dots 3 and 6 to the pattern for B, giving dots 1, 2, 3, and 6.',10,2,array['letters'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0824','braille','Letters','hard','classic','Which letter uses Braille dots 2, 4, 5, and 6?','["W","J","T","Y"]'::jsonb,'W','W is dots 2, 4, 5, and 6; it does not follow the regular pattern because French Braille had no W.',10,2,array['letters'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0825','braille','Letters','hard','classic','Which dots represent the Braille letter X?','["Dots 1, 3, 4, and 6","Dots 1, 3, 4, 5, and 6","Dots 1, 3, 5, and 6","Dots 1, 3, and 6"]'::jsonb,'Dots 1, 3, 4, and 6','X adds dots 3 and 6 to the pattern for C, giving dots 1, 3, 4, and 6.',10,2,array['letters'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0826','braille','Letters','expert','classic','Which letter uses Braille dots 1, 3, 4, 5, and 6?','["Y","X","Z","Q"]'::jsonb,'Y','Y adds dots 3 and 6 to the pattern for D, giving dots 1, 3, 4, 5, and 6.',10,2,array['letters'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0827','management','Planning','easy','classic','What is a Gantt chart used for?','["Showing a project schedule as tasks across time","Recording daily cash sales","Drawing an organization’s hierarchy","Collecting customer complaints"]'::jsonb,'Showing a project schedule as tasks across time','A Gantt chart shows each task as a bar along a timeline, with start and end dates.',10,2,array['planning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0828','management','Projects','medium','classic','What is the purpose of a project scope statement?','["To define what work is included in and excluded from a project","To list every employee’s salary","To record the company’s share price","To describe the office floor plan"]'::jsonb,'To define what work is included in and excluded from a project','A clear scope statement sets boundaries and helps prevent misunderstandings.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0829','management','Leadership','medium','classic','What is micromanagement?','["Controlling every small detail of others’ work too closely","Delegating tasks with clear authority","Setting long-term strategy","Hiring an outside contractor"]'::jsonb,'Controlling every small detail of others’ work too closely','Micromanagement can reduce trust, motivation, and team independence.',10,2,array['leadership'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0830','management','Quality','medium','classic','What is benchmarking?','["Comparing performance with leading practices or peers","Fixing the price of a product","Counting stock at the end of a year","Writing a job advertisement"]'::jsonb,'Comparing performance with leading practices or peers','Benchmarking identifies gaps and ideas for improvement.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0831','management','Quality','medium','classic','What do the letters in the PDCA improvement cycle stand for?','["Plan, Do, Check, Act","Prepare, Deliver, Close, Audit","Plan, Design, Code, Assess","Propose, Decide, Control, Adjust"]'::jsonb,'Plan, Do, Check, Act','The Plan-Do-Check-Act cycle supports continuous improvement in quality management.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0832','management','Strategy','easy','classic','What is a mission statement?','["A short statement of an organization’s purpose","A detailed financial forecast","A list of products for sale","An advertisement for a job opening"]'::jsonb,'A short statement of an organization’s purpose','A mission statement explains why an organization exists and whom it serves.',10,2,array['strategy'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0833','management','Organization','medium','classic','What does span of control mean?','["The number of people a manager directly supervises","The size of a department’s budget","The length of a project","The number of products a firm sells"]'::jsonb,'The number of people a manager directly supervises','A wide span of control means a manager has many direct reports.',10,2,array['organization'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0834','management','Projects','medium','classic','What is scope creep?','["Uncontrolled growth in a project’s requirements","Planned reduction of project work","A delay in paying suppliers","High staff turnover"]'::jsonb,'Uncontrolled growth in a project’s requirements','Scope creep happens when extra work is added without adjusting time, cost, or resources.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0835','management','Stakeholders','easy','classic','Who is a stakeholder in a project?','["Anyone who affects or is affected by the project","Only the project’s shareholders","Only the project manager","Only the customers who pay"]'::jsonb,'Anyone who affects or is affected by the project','Stakeholders can include staff, customers, suppliers, regulators, and the community.',10,2,array['stakeholders'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0836','management','People','medium','classic','What is succession planning?','["Preparing people to fill key roles in the future","Merging two companies","Launching a new product","Cutting the annual budget"]'::jsonb,'Preparing people to fill key roles in the future','Succession planning reduces disruption when leaders or key staff leave.',10,2,array['people'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0837','business','Marketing','easy','classic','What is a brand?','["A name, design, or identity that sets a seller’s products apart","A tax paid on sales","A type of bank loan","A storage warehouse"]'::jsonb,'A name, design, or identity that sets a seller’s products apart','Brands help customers recognize and trust products.',10,2,array['marketing'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0838','business','Enterprise','easy','classic','What is an entrepreneur?','["A person who starts and runs a new business, taking on risk","A government tax official","A salaried employee with no stake","An external auditor"]'::jsonb,'A person who starts and runs a new business, taking on risk','Entrepreneurs organize resources to turn an idea into a business.',10,2,array['enterprise'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0839','business','Ownership','easy','classic','What is a sole proprietorship?','["A business owned and run by one person","A business owned by the government","A company listed on a stock exchange","A partnership of two or more people"]'::jsonb,'A business owned and run by one person','In a sole proprietorship the owner keeps the profits and usually bears unlimited liability.',10,2,array['ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0840','business','Finance','easy','classic','How is profit calculated?','["Revenue minus expenses","Revenue plus expenses","Total sales only","Cash held in the bank"]'::jsonb,'Revenue minus expenses','Profit is what remains after expenses are subtracted from revenue.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0841','business','Ownership','medium','classic','What is a franchise?','["A licence to run a business using another firm’s brand and system","A loan from a government bank","A tax break for exporters","A type of business insurance"]'::jsonb,'A licence to run a business using another firm’s brand and system','Franchisees pay fees to use the franchisor’s name, products, and methods.',10,2,array['ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0842','business','Operations','medium','classic','What is outsourcing?','["Contracting work to an outside provider","Selling products overseas","Hiring more full-time staff","Closing a factory"]'::jsonb,'Contracting work to an outside provider','Firms outsource tasks such as payroll or customer support to specialists.',10,2,array['operations'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0843','business','Planning','easy','classic','What is a business plan?','["A document describing a business’s goals, strategy, and finances","A list of employees’ holidays","A product’s instruction manual","A receipt for a large purchase"]'::jsonb,'A document describing a business’s goals, strategy, and finances','Business plans guide decisions and help secure funding.',10,2,array['planning'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0844','business','Customers','medium','classic','What is customer retention?','["Keeping existing customers over time","Attracting first-time visitors only","Refunding unhappy customers","Raising prices for regular customers"]'::jsonb,'Keeping existing customers over time','Retaining customers is often cheaper than winning new ones.',10,2,array['customers'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0845','business','Finance','medium','classic','What is the break-even point?','["The level of sales where total revenue equals total costs","The point where a firm stops advertising","The highest price customers will pay","The date a loan is fully repaid"]'::jsonb,'The level of sales where total revenue equals total costs','Below break-even a business makes a loss; above it, a profit.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0846','business','Strategy','medium','classic','What is a merger?','["Two companies combining to form one","A company splitting into two","A firm hiring new managers","A business closing permanently"]'::jsonb,'Two companies combining to form one','Mergers can create scale, new markets, or cost savings.',10,2,array['strategy'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0847','accounting','Elements','medium','classic','What is an asset in accounting?','["A resource controlled by an entity that is expected to bring future economic benefits","An amount the entity owes to others","A cost used up during the period","The owners’ residual interest"]'::jsonb,'A resource controlled by an entity that is expected to bring future economic benefits','Examples of assets include cash, inventory, equipment, and amounts receivable.',10,2,array['elements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0848','accounting','Elements','medium','classic','What is equity in accounting?','["The owners’ residual interest after deducting liabilities from assets","The total of all liabilities","The revenue earned in a year","The cash in the bank"]'::jsonb,'The owners’ residual interest after deducting liabilities from assets','Equity equals assets minus liabilities.',10,2,array['elements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0849','accounting','Statements','medium','classic','What does a cash flow statement show?','["Cash coming in and going out during a period","Financial position at a single date","Only the profit for the year","The list of shareholders"]'::jsonb,'Cash coming in and going out during a period','It groups cash flows into operating, investing, and financing activities.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0850','accounting','Bookkeeping','medium','classic','What is a trial balance?','["A list of ledger balances used to check that debits equal credits","A final audit opinion","A forecast of next year’s sales","A bank statement"]'::jsonb,'A list of ledger balances used to check that debits equal credits','A trial balance helps detect errors before financial statements are prepared.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0851','accounting','Bookkeeping','medium','classic','In bookkeeping, what is a journal?','["The book of original entry where transactions are first recorded","The final balance sheet","A report sent to shareholders","A list of customers"]'::jsonb,'The book of original entry where transactions are first recorded','Entries are recorded in the journal and then posted to ledger accounts.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0852','accounting','Elements','easy','classic','What is an expense?','["A cost used up in earning revenue during a period","Money invested by the owner","An amount customers owe the business","A long-term loan"]'::jsonb,'A cost used up in earning revenue during a period','Rent, wages, and electricity are common business expenses.',10,2,array['elements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0853','accounting','Profit','medium','classic','What is net profit?','["Revenue minus all expenses","Revenue minus cost of goods sold only","Total revenue before any costs","Cash received from customers"]'::jsonb,'Revenue minus all expenses','Net profit is what remains after every expense, including tax and interest, is deducted.',10,2,array['profit'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0854','accounting','Profit','medium','classic','How is gross profit calculated?','["Revenue minus cost of goods sold","Revenue minus all expenses","Assets minus liabilities","Cash in minus cash out"]'::jsonb,'Revenue minus cost of goods sold','Gross profit shows how much is earned from sales before operating expenses.',10,2,array['profit'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0855','accounting','Assets','hard','classic','What is amortization commonly used for in accounting?','["Spreading the cost of an intangible asset over its useful life","Recording cash sales","Valuing closing inventory","Paying dividends to shareholders"]'::jsonb,'Spreading the cost of an intangible asset over its useful life','Intangible assets such as patents are amortized; tangible assets are depreciated.',10,2,array['assets'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0856','accounting','Cash','easy','classic','What is petty cash?','["A small amount of cash kept for minor expenses","A long-term investment","A large bank loan","The owners’ capital"]'::jsonb,'A small amount of cash kept for minor expenses','Petty cash covers small costs such as postage or refreshments.',10,2,array['cash'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0857','commerce','Trade','easy','classic','What is barter?','["Exchanging goods or services directly without money","Buying goods on credit","Selling goods online","Paying by cheque"]'::jsonb,'Exchanging goods or services directly without money','Barter was common before money; for example, trading grain for cloth.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0858','commerce','Payments','medium','classic','How does paying by credit card work?','["The card issuer pays now and the cardholder repays later","Money is taken instantly from a savings account","The shop gives goods free of charge","The buyer pays only in cash later at the shop"]'::jsonb,'The card issuer pays now and the cardholder repays later','Credit cards provide short-term borrowing up to a set limit.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0859','commerce','Payments','easy','classic','What does a debit card do when used to pay?','["Takes the money directly from the cardholder’s bank account","Borrows money from the card issuer","Adds money to the account","Delays payment for a year"]'::jsonb,'Takes the money directly from the cardholder’s bank account','Debit card payments draw on funds already in the linked account.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0860','commerce','Consumers','easy','classic','Who is a consumer?','["A person who buys or uses goods and services","A person who only manufactures goods","A government tax collector","A bank that lends money"]'::jsonb,'A person who buys or uses goods and services','Consumers are the final users of goods and services.',10,2,array['consumers'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0861','commerce','Logistics','medium','classic','What is logistics?','["Planning and managing the movement and storage of goods","Designing product logos","Recording company accounts","Setting interest rates"]'::jsonb,'Planning and managing the movement and storage of goods','Logistics covers transport, warehousing, and delivery.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0862','commerce','Consumers','easy','classic','What is a product warranty?','["A promise to repair or replace a product if it is faulty within a set period","A discount on the next purchase","A tax on luxury goods","A delivery tracking number"]'::jsonb,'A promise to repair or replace a product if it is faulty within a set period','Warranties protect buyers against defects for a stated time.',10,2,array['consumers'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0863','commerce','Documents','medium','classic','What is a quotation in commerce?','["A seller’s statement of the price for goods or services","A receipt for payment","A government trade licence","A record of goods returned"]'::jsonb,'A seller’s statement of the price for goods or services','Buyers often compare quotations from several suppliers before ordering.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0864','commerce','Payments','easy','classic','What does cash on delivery mean?','["Payment is made when the goods are delivered","Payment is made a month before ordering","Goods are delivered free of charge","Payment is made only by cheque"]'::jsonb,'Payment is made when the goods are delivered','Cash on delivery is common in online shopping.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0865','commerce','Documents','medium','classic','What is a purchase order?','["A buyer’s document authorizing a purchase from a supplier","A seller’s request for payment","Proof that goods were delivered","A bank statement"]'::jsonb,'A buyer’s document authorizing a purchase from a supplier','The purchase order states items, quantities, and agreed prices.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0866','commerce','International trade','hard','classic','What is a letter of credit?','["A bank’s promise to pay a seller once agreed conditions are met","A letter thanking a customer","A credit card statement","A request for a discount"]'::jsonb,'A bank’s promise to pay a seller once agreed conditions are met','Letters of credit reduce payment risk in international trade.',10,2,array['international trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
